'use server'

import { refresh } from 'next/cache'
import { cookies } from 'next/headers'

const NOTIFICATION_PREFERENCE_COOKIE = 'notifications-enabled'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()
  const notificationsEnabled =
    cookieStore.get(NOTIFICATION_PREFERENCE_COOKIE)?.value === 'true'

  cookieStore.set(
    NOTIFICATION_PREFERENCE_COOKIE,
    notificationsEnabled ? 'false' : 'true',
    {
      httpOnly: true,
      path: '/',
      sameSite: 'lax',
    },
  )

  refresh()
}

